#include "event_bus.hpp"

#include <cassert>
#include <iostream>

int main() {
    {
        EventLog log(10);
        EventBus bus(log);
        int count = 0;
        bus.subscribe("orders", [&count](const Event&) { count++; });
        bus.publish("orders", "o1");
        assert(count == 1);

        bus.muteTopic("orders");
        int invoked = bus.publish("orders", "o2");
        assert(invoked == 0);
        assert(count == 1);
        assert(log.size() == 2); /* still logged despite muting */

        int subResult = bus.subscribe("orders", [](const Event&) {});
        assert(subResult == -1);
    }
    {
        EventLog log(10);
        EventBus bus(log);
        bus.publish("orders", "o1");
        bus.publish("orders", "o2");

        int count = 0;
        bus.subscribe("orders", [&count](const Event&) { count++; });

        bus.muteTopic("orders");
        int replayed = bus.replay("orders");
        assert(replayed == 0);
        assert(count == 0);
    }
    std::cout << "PASS" << std::endl;
    return 0;
}

