#pragma once

#include <functional>
#include <string>
#include <unordered_map>
#include <unordered_set>
#include <utility>

#include "event.hpp"
#include "event_log.hpp"

class EventBus {
public:
    using Callback = std::function<void(const Event&)>;

    explicit EventBus(EventLog& log) : log_(log) {}

    void muteTopic(const std::string& topic) { muted_.insert(topic); }
    void unmuteTopic(const std::string& topic) { muted_.erase(topic); }

    /* Rejects (-1) subscribing to a muted topic - there's no point
     * registering a listener for a topic that won't fire. */
    int subscribe(const std::string& topic, Callback cb) {
        if (muted_.count(topic)) {
            return -1;
        }
        int id = next_id_++;
        subscribers_[id] = std::make_pair(topic, std::move(cb));
        return id;
    }

    void unsubscribe(int subscription_id) { subscribers_.erase(subscription_id); }

    /* Always logs the event (history is preserved even while muted),
     * but does not invoke subscribers for a muted topic. */
    int publish(const std::string& topic, const std::string& payload) {
        Event event{next_seq_++, topic, payload};
        log_.record(event);
        if (muted_.count(topic)) {
            return 0;
        }
        int invoked = 0;
        for (const auto& entry : subscribers_) {
            if (entry.second.first == topic) {
                entry.second.second(event);
                invoked++;
            }
        }
        return invoked;
    }

    /* Re-invokes every current subscriber of `topic` for every logged
     * history entry on that topic (e.g. a late subscriber catching up).
     * Must ALSO respect muting - returns 0 without invoking anyone if
     * the topic is muted, same as publish(). */
    int replay(const std::string& topic) {
        if (muted_.count(topic)) {
            return 0;
        }
        int invoked = 0;
        for (const auto& event : log_.history()) {
            if (event.topic != topic) {
                continue;
            }
            for (const auto& entry : subscribers_) {
                if (entry.second.first == topic) {
                    entry.second.second(event);
                    invoked++;
                }
            }
        }
        return invoked;
    }

private:
    EventLog& log_;
    std::unordered_map<int, std::pair<std::string, Callback>> subscribers_;
    std::unordered_set<std::string> muted_;
    int next_id_ = 1;
    long next_seq_ = 1;
};

